package in.aicon.pocket;
import android.content.*;import android.graphics.*;import android.net.Uri;import java.io.*;
/** Device-private, per-ledger avatar. Never included in Drive or ledger backups. */
final class ProfilePhotos {
 static File file(Context c,String key){if(!key.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid profile");return new File(c.getFilesDir(),"profile-"+key+".jpg");}
 static Bitmap load(Context c,String key){File f=file(c,key);return f.isFile()?BitmapFactory.decodeFile(f.getPath()):null;}
 static void save(Context c,String key,Uri uri)throws Exception{byte[] data;try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Photo unavailable");byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>12*1024*1024)throw new IOException("Choose a photo under 12 MB");out.write(buf,0,n);}data=out.toByteArray();}saveBytes(c,key,data);}
 static void saveBytes(Context c,String key,byte[] data)throws Exception{if(data.length>12*1024*1024)throw new IOException("Choose a smaller photo");BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,o);if(o.outWidth<=0||o.outHeight<=0||(long)o.outWidth*o.outHeight>40000000L)throw new IOException("Choose a supported photo under 40 megapixels");o.inJustDecodeBounds=false;o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>768)o.inSampleSize*=2;Bitmap b=BitmapFactory.decodeByteArray(data,0,data.length,o);if(b==null)throw new IOException("Photo could not be opened");try{android.media.ExifInterface exif=new android.media.ExifInterface(new ByteArrayInputStream(data));int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}if(!matrix.isIdentity()){Bitmap rotated=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),matrix,true);if(rotated!=b)b.recycle();b=rotated;}}catch(IOException ignored){}File dest=file(c,key),tmp=new File(dest.getPath()+".tmp");try{try(FileOutputStream out=new FileOutputStream(tmp)){if(!b.compress(Bitmap.CompressFormat.JPEG,90,out))throw new IOException("Photo could not be saved");out.getFD().sync();}if(!tmp.renameTo(dest))throw new IOException("Photo could not be saved");}finally{b.recycle();tmp.delete();}}
 static void remove(Context c,String key)throws IOException{File f=file(c,key);if(f.exists()&&!f.delete())throw new IOException("Photo could not be removed");}
}
